const adventureLabels={ru:{title:"Приключения МОГУ",sub:"Выбирай мир, знакомься с героями и открывай новое. Здесь можно пробовать снова и идти в своём темпе.",start:"Начать приключение",back:"К мирам",done:"Ты открыл это задание!",retry:"Попробуем ещё раз?",bridge:"Попробуй в настоящей жизни",stars:"Открытия",missions:"заданий",allDone:"Все задания этого мира пройдены. Можно играть снова!",buddy:"Боби приготовил тебе игру!",complete:"Я попробовал!",choose:"Выбери ответ",note:"Взрослый может подсказать, показать карточку или дать время. Любой способ ответа подходит."},kk:{title:"МОГУ оқиғалары",sub:"Әлемді таңда, кейіпкерлермен таныс және жаңалық аш. Қайта байқап көруге болады.",start:"Оқиғаны бастау",back:"Әлемдерге оралу",done:"Бұл тапсырманы аштың!",retry:"Қайта байқап көрейік пе?",bridge:"Өмірде бірге жасап көр",stars:"Жаңалықтар",missions:"тапсырма",allDone:"Бұл әлемнің тапсырмалары аяқталды. Қайта ойнауға болады!",buddy:"Боби саған ойын дайындады!",complete:"Мен байқап көрдім!",choose:"Жауапты таңда",note:"Ересек адам көмектесіп, суретті көрсете немесе күтуге мүмкіндік бере алады. Кез келген жауап тәсілі жарайды."},en:{title:"MOGU Adventures",sub:"Choose a world, meet the characters and discover something new. You can try again and go at your own pace.",start:"Start adventure",back:"Back to worlds",done:"You discovered this activity!",retry:"Shall we try again?",bridge:"Try it in real life",stars:"Discoveries",missions:"missions",allDone:"You explored every mission in this world. You can play again!",buddy:"Bobi has a game for you!",complete:"I tried it!",choose:"Choose an answer",note:"An adult can help, model a symbol or give more time. Any way of answering is welcome."}};
function renderAdventures(){state.screen="adventures";const l=state.lang,L=adventureLabels[l],progress=store.get("adventure-done",[]),active=state.adventureTrack;const total=adventureTracks.reduce((n,x)=>n+x.missions.length,0);$("#app-main").innerHTML=head(L.title,L.sub)+'<div class="adventure-hero"><img src="./assets/bobi.svg" alt="Боби"><div><strong>'+L.buddy+'</strong><p>'+L.sub+'</p><span>⭐ '+progress.length+' / '+total+' '+L.stars+'</span></div></div>'+(active===undefined||active===null?'<div class="adventure-worlds">'+adventureTracks.map((w,i)=>{const done=w.missions.filter(m=>progress.includes(w.key+":"+m[0])).length;return '<button class="adventure-world" data-adventure="'+i+'"><span class="adventure-icon">'+w.icon+'</span><strong>'+w.name[l==="kk"?1:l==="en"?2:0]+'</strong><small>'+w.about[l==="kk"?1:l==="en"?2:0]+'</small><span class="adventure-meter">'+done+' / '+w.missions.length+' ⭐</span></button>'}).join("")+'</div>':'');if(active!==undefined&&active!==null){const w=adventureTracks[active];const mi=state.adventureMission||0;const m=w.missions[mi];const id=w.key+":"+m[0];const done=progress.includes(id);$("#app-main").innerHTML+= '<section class="adventure-play"><button class="soft-button" data-action="adventure-back">← '+L.back+'</button><div class="adventure-progress">'+w.icon+' '+w.name[l==="kk"?1:l==="en"?2:0]+' · '+(mi+1)+' / '+w.missions.length+'</div><div class="adventure-mascot">✨</div><h2>'+m[2][l==="kk"?1:l==="en"?2:0]+'</h2><p class="adventure-question">'+m[3][l==="kk"?1:l==="en"?2:0]+'</p><div class="adventure-options">'+m[4].map((o,i)=>'<button class="adventure-option" data-mission-answer="'+i+'"><span>'+o[0]+'</span><strong>'+o[l==="kk"?1:l==="en"?2:0]+'</strong></button>').join("")+'</div><p class="adventure-feedback" aria-live="polite">'+(done?L.done:state.adventureFeedback||L.note)+'</p><div class="adventure-bridge"><strong>'+L.bridge+'</strong><p>'+m[6][l==="kk"?1:l==="en"?2:0]+'</p></div>'+(done?'<button class="adventure-next" data-action="adventure-next">'+(mi===w.missions.length-1?L.back:L.start+' →')+'</button>':'<button class="adventure-next" data-action="adventure-complete">'+L.complete+'</button>')+'<p class="adventure-note">'+L.note+'</p></section>'}}
function selectAdventure(i){state.adventureTrack=i;state.adventureMission=0;state.adventureFeedback="";renderAdventures()}
function renderLearn(){state.screen="learn";const l=state.lang;const title=l==="kk"?"Үйренемін":l==="en"?"I learn":"Учусь";$("#app-main").innerHTML=head(title,l==="kk"?"Ойын арқылы жаңа дағдыларды үйренеміз":l==="en"?"Learn through play, at your own pace":"Изучаем новое через игру, в своём темпе")+'<div class="learn-hub"><img src="./assets/bobi.svg" alt="Боби"><div><strong>'+(l==="kk"?"Сәлем! Мен Бобимін!":l==="en"?"Hello! I'm Bobi!":"Привет! Я Боби!")+'</strong><p>'+(l==="kk"?"Бүгін не үйренеміз?":l==="en"?"What shall we discover today?":"Что сегодня откроем?")+'</p><button class="adventure-next" data-screen="adventures">'+adventureLabels[l].start+' →</button></div></div><div class="learn-topic-grid">'+[["🎨",["Цвета и формы","Түстер мен пішіндер","Colours and shapes"],"colors"],["🔢",["Счёт и числа","Санау және сандар","Counting and numbers"],"math"],["🔤",["Буквы и чтение","Әріптер мен оқу","Letters and reading"],"reading"],["🧩",["Логика и память","Логика және есте сақтау","Logic and memory"],"thinking"],["🗣️",["Слова и речь","Сөздер мен сөйлеу","Words and language"],"language"],["🌱",["Навыки жизни","Өмірлік дағдылар","Life skills"],"daily"]].map(x=>'<button class="learn-topic" data-adventure="'+adventureTracks.findIndex(w=>w.key===x[2])+'"><span>'+x[0]+'</span><strong>'+x[1][l==="kk"?1:l==="en"?2:0]+'</strong></button>').join("")+'</div>';nav("home")}
function renderLearn(){state.screen="learn";const set=lessonSets[activeLesson];if(!state.lesson||state.lesson.topic!==activeLesson)newLesson();const L=state.lesson;$("#app-main").innerHTML=head(t("learn"),t("learnDesc"))+'<div class="learn-layout"><section class="learn-main"><div class="lesson-kicker">'+t(activeLesson)+'</div><h2 class="lesson-question">'+t("chooseAnswer")+'<br><span>'+t(L.prompt)+'</span></h2><div class="lesson-options">'+L.options.map((x,i)=>'<button class="lesson-option" data-answer="'+x[0]+'"><span>'+x[1]+'</span><strong>'+t(x[0])+'</strong></button>').join("")+'</div><p class="lesson-feedback" aria-live="polite">'+state.feedback+'</p><button class="soft-button" data-action="repeat">🔊 '+t("again")+'</button> <button class="soft-button" data-action="newlesson">'+t("next")+' →</button></section><aside class="lesson-side"><div class="panel buddy-card"><img src="./assets/bobi.svg" alt="Боби"><p>'+t("youCan")+'</p></div><div class="panel lesson-tools">'+Object.keys(lessonSets).map(k=>'<button class="category-button '+(activeLesson===k?"active":"")+'" data-lesson="'+k+'">'+t(k)+'</button>').join("")+'</div></aside></div>';nav("home")}
function newLesson(){const set=lessonSets[activeLesson];const target=set[Math.floor(Math.random()*set.length)];const others=set.filter(x=>x!==target).sort(()=>Math.random()-.5).slice(0,2);const options=[target,...others].sort(()=>Math.random()-.5);state.lesson={topic:activeLesson,prompt:target[0],answer:target[0],options};state.feedback=""}
function renderWorld(){state.screen="world";const groups=["animals","food","home","clothes","transport","nature"];$("#app-main").innerHTML=head(t("world"),t("worldDesc"))+'<div class="section-head"><h2>'+t("explore")+'</h2><span class="hint">🌱</span></div><div class="world-grid">'+worldData.map(x=>'<button class="world-card" data-world="'+x[0]+'" data-icon="'+x[1]+'"><span class="pic">'+x[1]+'</span><strong>'+t(x[0])+'</strong><small>'+t(x[2])+'</small></button>').join("")+'</div>'+(state.worldItem?'<div class="detail-card"><span class="detail-pic">'+state.worldItem.icon+'</span><div><h3>'+t(state.worldItem.key)+'</h3><p>'+t("explore")+'</p></div><button class="soft-button" data-action="worldsay">🔊</button></div>':"");nav("home")}
function renderFeel(){state.screen="feel";$("#app-main").innerHTML=head(t("feel"),t("feelDesc"))+'<div class="section-head"><h2>'+t("iFeel")+'</h2><span class="hint">💜</span></div><div class="panel buddy-card feel-guide"><img src="./assets/luna.svg" alt="Луна"><p>'+t("youCan")+'</p></div><div class="feel-grid">'+emotions.map(x=>'<button class="feel-card" data-feel="'+x[0]+'"><span class="pic">'+x[1]+'</span>'+t(x[0])+'</button>').join("")+'</div>'+(state.feeling?'<div class="feel-selected"><span class="pic">'+state.feeling.icon+'</span><div><h3>'+t(state.feeling.key)+'</h3><p>'+t("iFeel")+' '+t(state.feeling.key).toLowerCase()+'</p></div><button class="soft-button" data-action="feeladd">'+t("addTalk")+'</button><button class="soft-button" data-action="feelsay">🔊</button></div>':"");nav("home")}
function renderProgress(){state.screen="progress";$("#app-main").innerHTML=head(t("progress"),t("progressNote"))+'<div class="progress-grid"><div class="stat-card"><span class="stat-icon">🗣️</span><strong>'+state.stats.spoken+'</strong><small>'+t("spoken")+'</small></div><div class="stat-card"><span class="stat-icon">🔎</span><strong>'+state.stats.explored+'</strong><small>'+t("explored")+'</small></div><div class="stat-card"><span class="stat-icon">🧩</span><strong>'+state.stats.lessons+'</strong><small>'+t("lessons")+'</small></div><div class="stat-card"><span class="stat-icon">💜</span><strong>'+state.stats.feelings+'</strong><small>'+t("feelings")+'</small></div></div><div class="adventure-progress-summary">🗺️ <strong>'+store.get("adventure-done",[]).length+' / '+adventureTracks.reduce((n,w)=>n+w.missions.length,0)+'</strong> '+(state.lang==="kk"?"МОГУ оқиғаларындағы тапсырмалар":state.lang==="en"?"MOGU adventure missions explored":"заданий в Приключениях МОГУ")+'</div><div class="progress-note">🌟 '+t("progressNote")+'</div>';nav("progress")}
function renderAdult(){state.screen="adult";const s=state.settings;$("#app-main").innerHTML=head(t("adult"),t("settings"))+"<button class=\"method-entry\" data-action=\"method\">🌱 <span class=\"method-title\">Методика развития МОГУ</span> →</button>"+'<div class="adult-grid"><section class="setting-card"><h3>'+t("size")+'</h3><p>'+t("size")+'</p><div class="setting-control">'+["normal","large","xlarge"].map(v=>'<button class="'+(s.size===v?"selected":"")+'" data-setting="size" data-value="'+v+'">'+t(v)+'</button>').join("")+'</div></section><section class="setting-card"><h3>'+t("simple")+'</h3><p>'+t("simple")+'</p><div class="setting-control"><button class="'+(!s.simple?"selected":"")+'" data-setting="simple" data-value="false">'+t("off")+'</button><button class="'+(s.simple?"selected":"")+'" data-setting="simple" data-value="true">'+t("on")+'</button></div></section><section class="setting-card"><h3>'+t("motion")+'</h3><p>'+t("motion")+'</p><div class="setting-control"><button class="'+(s.motion?"selected":"")+'" data-setting="motion" data-value="true">'+t("on")+'</button><button class="'+(!s.motion?"selected":"")+'" data-setting="motion" data-value="false">'+t("off")+'</button></div></section><section class="setting-card"><h3>'+t("rate")+'</h3><p>'+t("rate")+'</p><div class="setting-control"><button data-setting="rate" data-value="0.7">Медленно</button><button data-setting="rate" data-value="0.85">Обычно</button><button data-setting="rate" data-value="1">Быстрее</button></div></section></div><div class="privacy-note">🔒 '+t("privacy")+'</div>';nav("adult")}
function applySettings(){document.body.classList.toggle("large-cards",state.settings.size==="large");document.body.classList.toggle("xlarge-cards",state.settings.size==="xlarge");document.body.classList.toggle("simple-mode",state.settings.simple);document.body.classList.toggle("reduced-motion",!state.settings.motion)}
function render(){document.documentElement.lang=state.lang==="kk"?"kk":state.lang;applySettings();$("#top-welcome").textContent=t("welcome");document.querySelectorAll(".lang-button").forEach(b=>{const active=b.dataset.lang===state.lang;b.classList.toggle("is-active",active);b.setAttribute("aria-pressed",String(active))});if(state.screen==="home")home();if(state.screen==="talk")renderTalk();if(state.screen==="learn")renderLearn();if(state.screen==="adventures")renderAdventures();if(state.screen==="world")renderWorld();if(state.screen==="feel")renderFeel();if(state.screen==="progress")renderProgress();if(state.screen==="adult")renderAdult();if(state.screen==="method")renderMethod()}
function setLang(lang){if(!words[lang])return;state.lang=lang;document.documentElement.lang=lang==="kk"?"kk":lang;store.set("language",lang);render()}
document.addEventListener("click",e=>{const fav=e.target.closest("[data-fav]");if(fav){e.preventDefault();e.stopPropagation();const key=fav.dataset.fav;favoriteKeys=favoriteKeys.includes(key)?favoriteKeys.filter(x=>x!==key):[key,...favoriteKeys];store.set("favorites",favoriteKeys);renderTalk();return}const b=e.target.closest("button");if(!b)return;
if(b.dataset.lang){setLang(b.dataset.lang);return}
if(b.dataset.screen){state.screen=b.dataset.screen;render();return}
if(b.dataset.nav){state.screen=b.dataset.nav==="talk"?"talk":b.dataset.nav==="progress"?"progress":b.dataset.nav==="adult"?"adult":"home";render();return}
if(b.dataset.adventure!==undefined){selectAdventure(Number(b.dataset.adventure));return}if(b.dataset.missionAnswer!==undefined){const w=adventureTracks[state.adventureTrack],m=w.missions[state.adventureMission],choice=Number(b.dataset.missionAnswer),l=state.lang;state.adventureFeedback=choice===m[5]?(l==="kk"?"Жарайсың! Дұрыс!":l==="en"?"Great discovery!":"У тебя получилось! Отличное открытие!"):(l==="kk"?"Қайта байқап көр. Асықпа!":l==="en"?"Try another choice. Take your time!":"Попробуй ещё раз. Не спеши!");renderAdventures();return}if(b.dataset.methodArea!==undefined){state.methodArea=Number(b.dataset.methodArea);renderMethod();return}if(b.dataset.methodStatus){const statuses=store.get("method-status",{});statuses[b.dataset.methodStatus]=Number(b.dataset.value);store.set("method-status",statuses);renderMethod();return}if(b.dataset.action){const a=b.dataset.action;if(a==="home"){state.screen="home";render()}if(a==="adventure-back"){state.adventureTrack=null;state.adventureMission=0;renderAdventures()}if(a==="adventure-complete"){const w=adventureTracks[state.adventureTrack],m=w.missions[state.adventureMission],id=w.key+":"+m[0],done=store.get("adventure-done",[]);if(!done.includes(id)){done.push(id);store.set("adventure-done",done)}state.adventureFeedback="";renderAdventures()}if(a==="adventure-next"){const w=adventureTracks[state.adventureTrack];if(state.adventureMission<w.missions.length-1){state.adventureMission++;state.adventureFeedback="";renderAdventures()}else{state.adventureTrack=null;state.adventureMission=0;renderAdventures()}}if(a==="method"){state.methodArea=null;renderMethod()}if(a==="method-close"){state.methodArea=null;renderMethod()}if(a==="undo"){state.phrase=state.history.pop()||[];renderTalk()}if(a==="remove"){if(state.phrase.length){state.history.push(state.phrase.slice());state.phrase.pop()}renderTalk()}if(a==="clear"){state.history.push(state.phrase.slice());state.phrase=[];renderTalk()}if(a==="say"){if(!state.phrase.length){toast(t("speakFirst"));return}const phrase=state.phrase.map(x=>t(x.key)).join(", ");speak(phrase);state.stats.spoken++;saveStats()}if(a==="repeat")speak(t(state.lesson.prompt));if(a==="newlesson"){newLesson();renderLearn()}if(a==="worldsay"&&state.worldItem)speak(t(state.worldItem.key));if(a==="feelsay"&&state.feeling)speak(t("iFeel")+" "+t(state.feeling.key));if(a==="feeladd"&&state.feeling){addPhrase(state.feeling.key,state.feeling.icon);state.screen="talk"}return}
if(b.dataset.category){state.category=b.dataset.category;renderTalk();return}
if(b.dataset.picto){addPhrase(b.dataset.picto,b.dataset.icon);return}
if(b.dataset.urgent){urgentAction(b.dataset.urgent);return}
if(b.dataset.lesson){activeLesson=b.dataset.lesson;newLesson();renderLearn();return}
if(b.dataset.answer){const correct=b.dataset.answer===state.lesson.answer;state.feedback=correct?t("great"):t("try");state.stats.lessons++;saveStats();renderLearn();const target=document.querySelector('[data-answer="'+b.dataset.answer+'"]');if(target&&correct)target.classList.add("correct");return}
if(b.dataset.world){state.worldItem={key:b.dataset.world,icon:b.dataset.icon};state.stats.explored++;saveStats();renderWorld();return}
if(b.dataset.feel){state.feeling={key:b.dataset.feel,icon:emotions.find(x=>x[0]===b.dataset.feel)[1]};state.stats.feelings++;saveStats();renderFeel();return}
if(b.dataset.setting){const k=b.dataset.setting,v=b.dataset.value;state.settings[k]=k==="size"?v:k==="rate"?Number(v):v==="true";store.set("settings",state.settings);renderAdult();applySettings();return}
});
try{const saved=store.get("language","ru");if(words[saved])state.lang=saved}catch(_){}
render();
if("serviceWorker"in navigator&&location.protocol!=="file:")window.addEventListener("load",()=>navigator.serviceWorker.register("./sw.js").catch(()=>{}));